 1	import { useEffect } from "react";
 2	import { settingAnchorSelector } from "~/components/settings/utils/settingAnchor";
 3	
 4	/** Roughly 500ms at 60fps. */
 5	const MAX_LOOKUP_FRAMES = 30;
 6	const FLASH_HOLD_MS = 600;
 7	const FLASH_FADE_MS = 700;
 8	
 9	/** `-mx-2 px-2` widens the highlight past the row's content without moving it. */
10	const FLASH_FRAME_CLASSES = [
11	  "-mx-2",
12	  "px-2",
13	  "rounded",
14	  "transition-colors",
15	  "duration-700",
16	];
17	const FLASH_FILL_CLASS = "bg-gray-100";
18	
19	const flashTimeouts = new WeakMap<Element, number[]>();
20	
21	/** Owns the flash independently of the effect: settling clears anchorId and re-runs the
22	 *  effect, whose cleanup would otherwise strip the classes before they are seen. */
23	const flashRow = (target: Element): void => {
24	  flashTimeouts.get(target)?.forEach((id) => window.clearTimeout(id));
25	
26	  target.classList.add(...FLASH_FRAME_CLASSES, FLASH_FILL_CLASS);
27	  flashTimeouts.set(target, [
28	    // Dropping the fill while the transition class is still on fades it out.
29	    window.setTimeout(
30	      () => target.classList.remove(FLASH_FILL_CLASS),
31	      FLASH_HOLD_MS,
32	    ),
33	    window.setTimeout(() => {
34	      target.classList.remove(...FLASH_FRAME_CLASSES);
35	      flashTimeouts.delete(target);
36	    }, FLASH_HOLD_MS + FLASH_FADE_MS),
37	  ]);
38	};
39	
40	/** The row is not in the DOM when the jump is dispatched — only the active panel renders,
41	 *  and a `Collapse` mounts later still — so a single lookup misses and this retries. */
42	export const useSettingAnchorScroll = ({
43	  anchorId,
44	  onSettled,
45	}: {
46	  anchorId: string | null;
47	  onSettled: () => void;
48	}): void => {
49	  useEffect(() => {
50	    if (!anchorId) return;
51	    let frame = 0;
52	    let rafId = 0;
53	
54	    const look = () => {
55	      const target = document.querySelector(settingAnchorSelector(anchorId));
56	      if (target) {
57	        target.scrollIntoView({ block: "center", behavior: "smooth" });
58	        flashRow(target);
59	        onSettled();
60	        return;
61	      }
62	      if (frame++ >= MAX_LOOKUP_FRAMES) {
63	        onSettled();
64	        return;
65	      }
66	      rafId = requestAnimationFrame(look);
67	    };
68	
69	    rafId = requestAnimationFrame(look);
70	    return () => cancelAnimationFrame(rafId);
71	  }, [anchorId, onSettled]);
72	};
 1	const SETTING_ANCHOR_ATTRIBUTE = "data-setting-id";
 2	
 3	/** Addressed by setting key, not tab, so the anchor survives a row moving tabs. */
 4	export const settingAnchor = (
 5	  settingKeys: string[],
 6	): Record<string, string> => ({
 7	  [SETTING_ANCHOR_ATTRIBUTE]: settingKeys.join("/"),
 8	});
 9	
10	/** Escaped so a key with a quote or backslash cannot break the selector. */
11	export const settingAnchorSelector = (anchorId: string): string =>
12	  `[${SETTING_ANCHOR_ATTRIBUTE}="${anchorId.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"]`;
 1	import type { TabId } from "@blueprintjs/core";
 2	import {
 3	  SETTINGS_TAB_IDS,
 4	  isSettingsTabId,
 5	  resolveSettingsTabId,
 6	} from "./settingsTabs";
 7	
 8	/** Settings dialog route: `["grammar-nodes", nodeTypeUid, "template"]`, tab first. */
 9	export type SettingsPath = readonly string[];
10	
11	export type SettingsNavAction =
12	  | { type: "select-tab"; tabId: string }
13	  | { type: "navigate"; path: SettingsPath }
14	  | { type: "push"; segment: string }
15	  | { type: "pop" }
16	  | { type: "truncate"; depth: number };
17	
18	export const nodeConfigSegmentIds = {
19	  index: "index",
20	  template: "template",
21	} as const;
22	
23	export const rootPath = (tabId: string): SettingsPath => [tabId];
24	
25	export const tabIdOf = (path: SettingsPath): string => path[0] ?? "";
26	
27	/** Drill-down segments below the tab; 0 is the tab's own root page. */
28	export const depthOf = (path: SettingsPath): number =>
29	  Math.max(0, path.length - 1);
30	
31	export const segmentsOf = (path: SettingsPath): readonly string[] =>
32	  path.slice(1);
33	
34	export const isSamePath = (a: SettingsPath, b: SettingsPath): boolean =>
35	  a.length === b.length && a.every((segment, index) => segment === b[index]);
36	
37	export const settingsNavReducer = (
38	  state: SettingsPath,
39	  action: SettingsNavAction,
40	): SettingsPath => {
41	  switch (action.type) {
42	    case "select-tab":
43	      return action.tabId === tabIdOf(state) && state.length === 1
44	        ? state
45	        : rootPath(action.tabId);
46	    // Search jumps several segments at once; an empty path is ignored.
47	    case "navigate":
48	      return action.path.length === 0 || isSamePath(action.path, state)
49	        ? state
50	        : [...action.path];
51	    case "push":
52	      return [...state, action.segment];
53	    case "pop":
54	      return state.length <= 1 ? state : state.slice(0, -1);
55	    case "truncate": {
56	      const length = Math.max(1, action.depth + 1);
57	      return length >= state.length ? state : state.slice(0, length);
58	    }
59	  }
60	};
61	
62	/** An id that is not a tab is a node type uid from the old per-node tabs; it opens
63	 *  inside Grammar > Nodes. */
64	export const resolveInitialSettingsPath = (
65	  selectedTabId?: TabId,
66	): SettingsPath => {
67	  const tabId = resolveSettingsTabId(selectedTabId);
68	  return isSettingsTabId(tabId)
69	    ? rootPath(tabId)
70	    : [SETTINGS_TAB_IDS.grammarNodes, String(tabId)];
71	};
72	
73	export type SettingsCrumb = {
74	  label: string;
75	  depth: number;
76	  isCurrent: boolean;
77	};
78	
79	export const buildBreadcrumbTrail = ({
80	  path,
81	  rootLabel,
82	  resolveLabel,
83	}: {
84	  path: SettingsPath;
85	  rootLabel: string;
86	  resolveLabel: (segment: string, segmentIndex: number) => string;
87	}): SettingsCrumb[] => {
88	  const segments = segmentsOf(path);
89	  return [
90	    { label: rootLabel, depth: 0, isCurrent: segments.length === 0 },
91	    ...segments.map((segment, index) => ({
92	      label: resolveLabel(segment, index),
93	      depth: index + 1,
94	      isCurrent: index === segments.length - 1,
95	    })),
96	  ];
97	};
 1	import React, { createContext, useContext, useMemo } from "react";
 2	import {
 3	  depthOf,
 4	  segmentsOf,
 5	  type SettingsNavAction,
 6	  type SettingsPath,
 7	} from "~/components/settings/utils/settingsNavigation";
 8	
 9	export type SettingsNavValue = {
10	  path: SettingsPath;
11	  depth: number;
12	  segments: readonly string[];
13	  push: (segment: string) => void;
14	  pop: () => void;
15	  goToDepth: (depth: number) => void;
16	  /** Jumps straight to a full route; `push` only moves one segment at a time. */
17	  navigate: (path: SettingsPath) => void;
18	};
19	
20	const SettingsNavContext = createContext<SettingsNavValue | null>(null);
21	
22	export const SettingsNavProvider = ({
23	  path,
24	  dispatch,
25	  children,
26	}: {
27	  path: SettingsPath;
28	  dispatch: React.Dispatch<SettingsNavAction>;
29	  children: React.ReactNode;
30	}): JSX.Element => {
31	  const value = useMemo<SettingsNavValue>(
32	    () => ({
33	      path,
34	      depth: depthOf(path),
35	      segments: segmentsOf(path),
36	      push: (segment) => dispatch({ type: "push", segment }),
37	      pop: () => dispatch({ type: "pop" }),
38	      goToDepth: (depth) => dispatch({ type: "truncate", depth }),
39	      navigate: (target) => dispatch({ type: "navigate", path: target }),
40	    }),
41	    [path, dispatch],
42	  );
43	  return (
44	    <SettingsNavContext.Provider value={value}>
45	      {children}
46	    </SettingsNavContext.Provider>
47	  );
48	};
49	
50	export const useSettingsNav = (): SettingsNavValue => {
51	  const context = useContext(SettingsNavContext);
52	  if (!context) {
53	    throw new Error("useSettingsNav must be used within a SettingsNavProvider");
54	  }
55	  return context;
56	};
