 49	const DiscourseNodeColorSetting = ({
 50	  canvasUid,
 51	  nodeType,
 52	  initialColor,
 53	  tagValue,
 54	}: DiscourseNodeColorSettingProps): React.ReactElement => {
 55	  const [color, setColor] = useState<string>(() =>
