145	const generateTagPlaceholder = (node: DiscourseNode): string => {
146	  // Extract first reference from format like [[CLM]], [[QUE]], [[EVD]]
147	  const referenceMatch = node.format.match(/\[\[([A-Z]+)\]\]/);
148	
149	  if (referenceMatch) {
150	    const reference = referenceMatch[1].toLowerCase();
151	    return `#${reference.slice(0, 3)}-candidate`; // [[EVD]] - {content} = #evd-candidate
152	  }
153	
154	  const nodeTextPrefix = node.text.toLowerCase().slice(0, 3);
155	  return `#${nodeTextPrefix}-candidate`; // Evidence = #evi-candidate
