181	  const [shortcutError, setShortcutError] = useState("");
182	
183	  const [tagValue, setTagValue] = useState(node.tag || "");
184	  const [formatValue, setFormatValue] = useState(node.format || "");
185	  const [shortcutValue, setShortcutValue] = useState(node.shortcut || "");
186	  const validate = useCallback(
187	    ({
188	      tag,
189	      format,
190	      isSpecificationEnabled,
191	    }: {
192	      tag: string;
193	      format: string;
194	      isSpecificationEnabled?: boolean;
195	    }) => {
196	      if (isSpecificationEnabled === undefined)
197	        isSpecificationEnabled =
198	          getDiscourseNodeSetting<boolean>(node.type, [
