216	      const matches = format.matchAll(roamTagRegex);
217	      const formatTags: string[] = [];
218	      for (const match of matches) {
219	        const tagName = match[1] || match[2];
220	        if (tagName) {
221	          formatTags.push(tagName.toUpperCase());
222	        }
223	      }
224	
225	      const hasConflict = formatTags.includes(cleanTag);
226	
227	      if (hasConflict) {
228	        setFormatError(
229	          `The format references the node's tag "${tag}". Please use a different format or tag.`,
230	        );
231	        setTagError(
232	          `The tag "${tag}" is referenced in the format. Please use a different tag or format.`,
233	        );
234	      } else {
235	        setTagError("");
236	        setFormatError("");
237	      }
238	    },
239	    [node.type],
