278	      }
279	    },
280	    [validateShortcut],
281	  );
282	
283	  return (
284	    <div className="flex flex-col gap-6 p-1">
285	      <SettingsGroup title="Identity">
286	        <SettingItemRow
287	          label="Index"
288	          description={`The saved list of all ${node.text} pages \u2014 which pages appear and which columns show.`}
289	          scope="global"
290	          settingKeys={[DISCOURSE_NODE_KEYS.index]}
291	          control={
292	            <SettingDrillDownSummary
