 17	  if (depth === 0) return null;
 18	
 19	  // depth > 0, so the trail always has a root crumb plus at least one segment.
 20	  const trail = buildBreadcrumbTrail({ path, rootLabel, resolveLabel });
 21	  const current = trail[trail.length - 1];
 22	  const parent = trail[trail.length - 2];
 23	
